// apps/client/src/calendar/CalendarItemDetailsModal.tsx
import React, { useState } from 'react';
import { Modal, Pressable, ScrollView, StyleSheet, Text, View } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { useRouter } from 'expo-router';
import ConfirmDialog from '@/components/ConfirmDialog';
import Button from '@/components/Button';
import { errorMessage } from '@/api/client';
import { colors } from '@/theme/colors';
import { CALENDAR_CATEGORY_COLORS, CalendarItem } from '@/types/calendar';
import { formatCalendarDate, formatCalendarTime, itemRangeLabel } from './calendarDates';
import { CategoryTag, IconName, SOFT, SURFACE, prettyStatus, tint } from './calendarUi';

type Props = { item: CalendarItem | null; onClose: () => void; onEdit: (item: CalendarItem) => void; onDelete: (item: CalendarItem) => Promise<void> };

export default function CalendarItemDetailsModal({ item, onClose, onEdit, onDelete }: Props) {
  const router = useRouter();
  const [confirm, setConfirm] = useState(false);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState('');
  if (!item) return null;
  const currentItem = item;
  const color = CALENDAR_CATEGORY_COLORS[currentItem.category];
  const sourceLabel = currentItem.source === 'CALENDAR_EVENT' ? 'Calendar event' : currentItem.source === 'LEAD_FOLLOWUP' ? 'Lead follow-up' : currentItem.source === 'REMINDER' ? 'Reminder' : 'Meeting';

  function openSource() {
    if (currentItem.leadId) {
      router.push({ pathname: '/lead/[id]', params: { id: currentItem.leadId, section: currentItem.source === 'LEAD_FOLLOWUP' ? 'followups' : currentItem.source === 'REMINDER' ? 'reminders' : 'meetings' } });
    } else if (currentItem.source === 'REMINDER') router.push('/reminders');
    else if (currentItem.source === 'MEETING') router.push('/meetings');
  }

  async function remove() {
    setBusy(true);
    setError('');
    try {
      await onDelete(currentItem);
      setConfirm(false);
      onClose();
    } catch (cause) {
      setError(errorMessage(cause));
    } finally {
      setBusy(false);
    }
  }

  const when = currentItem.allDay
    ? itemRangeLabel(currentItem)
    : currentItem.endAt
      ? itemRangeLabel(currentItem)
      : `${formatCalendarDate(currentItem.startAt)} ${formatCalendarTime(currentItem.startAt)}`;

  return (
    <>
      <Modal visible transparent animationType="fade" onRequestClose={onClose}>
        <View style={styles.overlay}>
          <View style={styles.modal}>
            <View style={styles.header}>
              <Text style={styles.title}>Calendar Details</Text>
              <Pressable accessibilityRole="button" accessibilityLabel="Close details" onPress={onClose} hitSlop={8} style={styles.closeButton}>
                <Ionicons name="close" size={20} color={colors.primaryText} />
              </Pressable>
            </View>

            <ScrollView contentContainerStyle={styles.body}>
              <View style={[styles.hero, { backgroundColor: tint(color, '14'), borderLeftColor: color }]}>
                <Text style={styles.eventTitle}>{currentItem.title}</Text>
                <View style={styles.tags}>
                  <CategoryTag category={currentItem.category} />
                  <View style={styles.sourceTag}><Text style={styles.sourceText}>{sourceLabel}</Text></View>
                </View>
              </View>

              <View style={styles.infoCard}>
                <InfoRow icon="time-outline" label="When" value={when} />
                <View style={styles.rowDivider} />
                <InfoRow icon="flag-outline" label="Status" value={currentItem.status ? prettyStatus(currentItem.status) : '—'} />
                <View style={styles.rowDivider} />
                <InfoRow icon="document-text-outline" label="Description" value={currentItem.description || '—'} />
              </View>

              {error ? (
                <View accessibilityRole="alert" style={styles.errorBox}>
                  <Ionicons name="alert-circle-outline" size={17} color={colors.danger} />
                  <Text style={styles.error}>{error}</Text>
                </View>
              ) : null}
            </ScrollView>

            <View style={styles.footer}>
              {currentItem.editable ? (
                <>
                  <Button title="Edit" variant="outline" onPress={() => onEdit(currentItem)} />
                  <Button title="Delete" variant="danger" onPress={() => setConfirm(true)} />
                </>
              ) : currentItem.source !== 'CALENDAR_EVENT' ? (
                <Button title="Open source" variant="outline" onPress={openSource} />
              ) : null}
              <Button title="Close" onPress={onClose} />
            </View>
          </View>
        </View>
      </Modal>

      <ConfirmDialog
        visible={confirm}
        title="Delete calendar event?"
        message="This event will be archived and removed from the calendar."
        loading={busy}
        onCancel={() => setConfirm(false)}
        onConfirm={() => { void remove(); }}
      />
    </>
  );
}

function InfoRow({ icon, label, value }: { icon: IconName; label: string; value: string }) {
  return (
    <View style={styles.infoRow}>
      <View style={styles.infoIcon}><Ionicons name={icon} size={16} color={colors.primaryText} /></View>
      <View style={styles.infoText}>
        <Text style={styles.label}>{label}</Text>
        <Text style={styles.value}>{value}</Text>
      </View>
    </View>
  );
}

const styles = StyleSheet.create({
  overlay: { flex: 1, backgroundColor: colors.overlay, alignItems: 'center', justifyContent: 'center', padding: 14 },
  modal: { width: '100%', maxWidth: 560, maxHeight: '88%', backgroundColor: colors.white, borderRadius: 16, overflow: 'hidden', boxShadow: '0 16px 40px rgba(14,27,61,0.24)' },

  header: { backgroundColor: colors.primary, paddingVertical: 14, paddingLeft: 20, paddingRight: 14, flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center' },
  title: { color: colors.primaryText, fontSize: 17, fontWeight: '800' },
  closeButton: { width: 34, height: 34, borderRadius: 17, alignItems: 'center', justifyContent: 'center', backgroundColor: 'rgba(255,255,255,0.22)' },

  body: { padding: 20, gap: 16 },
  hero: { gap: 10, paddingVertical: 14, paddingHorizontal: 16, borderLeftWidth: 5, borderRadius: 14 },
  eventTitle: { color: colors.text, fontSize: 19, fontWeight: '800', lineHeight: 25 },
  tags: { flexDirection: 'row', flexWrap: 'wrap', alignItems: 'center', gap: 6 },
  sourceTag: { borderRadius: 8, paddingHorizontal: 8, paddingVertical: 3, backgroundColor: SOFT },
  sourceText: { color: colors.muted, fontSize: 11, fontWeight: '700' },

  infoCard: { borderWidth: 1, borderColor: colors.border, borderRadius: 14, backgroundColor: SURFACE, paddingHorizontal: 14 },
  infoRow: { flexDirection: 'row', alignItems: 'flex-start', gap: 12, paddingVertical: 13 },
  infoIcon: { width: 32, height: 32, borderRadius: 10, alignItems: 'center', justifyContent: 'center', backgroundColor: colors.primarySoft },
  infoText: { flex: 1, minWidth: 0, gap: 3 },
  rowDivider: { height: 1, backgroundColor: colors.border },
  label: { color: colors.muted, fontSize: 12, fontWeight: '700' },
  value: { color: colors.text, fontSize: 14, lineHeight: 20 },

  errorBox: { flexDirection: 'row', alignItems: 'center', gap: 8, padding: 11, borderRadius: 10, backgroundColor: colors.dangerSoft },
  error: { flex: 1, color: colors.danger, fontSize: 12.5 },

  footer: { borderTopWidth: 1, borderTopColor: colors.border, paddingHorizontal: 20, paddingVertical: 14, flexDirection: 'row', justifyContent: 'flex-end', gap: 10, flexWrap: 'wrap' },
});

// apps/client/src/calendar/calendarDates.ts
import { CalendarItem, CalendarView } from '@/types/calendar';

const IST_MINUTES = 330;
const DAY_MS = 86400000;
const pad = (value: number) => String(value).padStart(2, '0');

export function todayIstKey(now = new Date()): string {
  const shifted = new Date(now.getTime() + IST_MINUTES * 60000);
  return `${shifted.getUTCFullYear()}-${pad(shifted.getUTCMonth() + 1)}-${pad(shifted.getUTCDate())}`;
}

export function parseDateKey(key: string): { year: number; month: number; day: number } {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(key);
  if (!match) throw new Error('Invalid calendar date key.');
  return { year: Number(match[1]), month: Number(match[2]), day: Number(match[3]) };
}

export function dateKeyToUtc(key: string): Date { const { year, month, day } = parseDateKey(key); return new Date(Date.UTC(year, month - 1, day)); }
export function dateKeyToIstMidnightIso(key: string): string { return new Date(dateKeyToUtc(key).getTime() - IST_MINUTES * 60000).toISOString(); }
export function dateTimeKeyToIstIso(key: string, time: string): string { const [hour, minute] = time.split(':').map(Number); return new Date(dateKeyToUtc(key).getTime() + (hour * 60 + minute - IST_MINUTES) * 60000).toISOString(); }
export function addDays(key: string, amount: number): string { const date = new Date(dateKeyToUtc(key).getTime() + amount * DAY_MS); return `${date.getUTCFullYear()}-${pad(date.getUTCMonth() + 1)}-${pad(date.getUTCDate())}`; }
export function addMonths(key: string, amount: number): string { const { year, month, day } = parseDateKey(key); const index = year * 12 + month - 1 + amount; const nextYear = Math.floor(index / 12); const nextMonth = index % 12 + 1; const maxDay = new Date(Date.UTC(nextYear, nextMonth, 0)).getUTCDate(); return `${nextYear}-${pad(nextMonth)}-${pad(Math.min(day, maxDay))}`; }
export function firstDayOfMonth(key: string): string { const { year, month } = parseDateKey(key); return `${year}-${pad(month)}-01`; }
export function lastDayOfMonth(key: string): string { const { year, month } = parseDateKey(key); return `${year}-${pad(month)}-${pad(new Date(Date.UTC(year, month, 0)).getUTCDate())}`; }
export function monthGridKeys(key: string): string[] { const first = firstDayOfMonth(key); const offset = dateKeyToUtc(first).getUTCDay(); const days = dateKeyToUtc(lastDayOfMonth(key)).getUTCDate(); const cells = Math.max(35, Math.ceil((offset + days) / 7) * 7); return Array.from({ length: cells }, (_, index) => addDays(first, index - offset)); }
export function visibleRange(view: CalendarView, selected: string): { from: string; to: string } { if (view === 'day') return { from: dateKeyToIstMidnightIso(selected), to: dateKeyToIstMidnightIso(addDays(selected, 1)) }; if (view === 'list') { const first = firstDayOfMonth(selected); return { from: dateKeyToIstMidnightIso(first), to: dateKeyToIstMidnightIso(addDays(first, dateKeyToUtc(lastDayOfMonth(selected)).getUTCDate())) }; } const grid = monthGridKeys(selected); return { from: dateKeyToIstMidnightIso(grid[0]), to: dateKeyToIstMidnightIso(addDays(grid[grid.length - 1], 1)) }; }
export function overlapsIstDay(item: CalendarItem, key: string): boolean { const from = dateKeyToIstMidnightIso(key); const to = dateKeyToIstMidnightIso(addDays(key, 1)); if (!item.endAt) return item.startAt >= from && item.startAt < to; return item.startAt < to && item.endAt > from; }
export function formatMonthHeading(key: string): string { return new Intl.DateTimeFormat('en-IN', { month: 'long', year: 'numeric', timeZone: 'UTC' }).format(dateKeyToUtc(key)); }
export function formatDayHeading(key: string): string { return new Intl.DateTimeFormat('en-IN', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric', timeZone: 'UTC' }).format(dateKeyToUtc(key)); }
export function formatDateKey(key: string): string { return new Intl.DateTimeFormat('en-IN', { day: '2-digit', month: 'short', year: 'numeric', timeZone: 'UTC' }).format(dateKeyToUtc(key)); }
export function formatCalendarTime(iso: string): string { return new Intl.DateTimeFormat('en-IN', { hour: '2-digit', minute: '2-digit', hourCycle: 'h23', timeZone: 'Asia/Kolkata' }).format(new Date(iso)); }
export function formatCalendarDate(iso: string): string { return new Intl.DateTimeFormat('en-IN', { day: '2-digit', month: 'short', year: 'numeric', timeZone: 'Asia/Kolkata' }).format(new Date(iso)); }
export function itemRangeLabel(item: CalendarItem): string { if (item.allDay && item.endAt) return `${formatDateKey(todayIstKey(new Date(item.startAt)))} – ${formatDateKey(addDays(todayIstKey(new Date(item.endAt)), -1))}`; if (!item.endAt) return formatCalendarTime(item.startAt); return `${formatCalendarDate(item.startAt)} ${formatCalendarTime(item.startAt)} – ${formatCalendarDate(item.endAt)} ${formatCalendarTime(item.endAt)}`; }

// apps/client/src/calendar/calendarUi.tsx
import React from 'react';
import { StyleSheet, Text, View } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { colors } from '@/theme/colors';
import { CALENDAR_CATEGORY_COLORS, CALENDAR_CATEGORY_LABELS, CalendarCategory } from '@/types/calendar';

export type IconName = React.ComponentProps<typeof Ionicons>['name'];

export const SURFACE = '#F7F9FC';
export const SOFT = '#EEF3FA';
export const TODAY_TINT = '#F2F7FF';

// Appends an alpha byte to a 6-digit hex colour, so every tint stays inside the existing category palette.
export const tint = (hex: string, alpha: string) => `${hex}${alpha}`;

export function prettyStatus(status: string) {
  const text = status.replace(/_/g, ' ').toLowerCase();
  return text.charAt(0).toUpperCase() + text.slice(1);
}

export function CategoryTag({ category }: { category: CalendarCategory }) {
  const color = CALENDAR_CATEGORY_COLORS[category];
  return (
    <View style={[styles.tag, { backgroundColor: tint(color, '1A') }]}>
      <View style={[styles.tagDot, { backgroundColor: color }]} />
      <Text style={styles.tagText}>{CALENDAR_CATEGORY_LABELS[category]}</Text>
    </View>
  );
}

export function StatusTag({ status }: { status: string }) {
  return (
    <View style={[styles.tag, { backgroundColor: SOFT }]}>
      <Text style={[styles.tagText, { color: colors.muted }]}>{prettyStatus(status)}</Text>
    </View>
  );
}

export function EmptyState({ icon, title, text }: { icon: IconName; title: string; text: string }) {
  return (
    <View style={styles.empty}>
      <View style={styles.emptyIcon}><Ionicons name={icon} size={26} color={colors.primaryText} /></View>
      <Text style={styles.emptyTitle}>{title}</Text>
      <Text style={styles.emptyText}>{text}</Text>
    </View>
  );
}

const styles = StyleSheet.create({
  tag: { flexDirection: 'row', alignItems: 'center', gap: 5, borderRadius: 8, paddingHorizontal: 8, paddingVertical: 3 },
  tagDot: { width: 6, height: 6, borderRadius: 3 },
  tagText: { color: colors.text, fontSize: 11, fontWeight: '700' },
  empty: { alignItems: 'center', gap: 8, paddingVertical: 48, paddingHorizontal: 24 },
  emptyIcon: { width: 56, height: 56, borderRadius: 28, backgroundColor: colors.primarySoft, alignItems: 'center', justifyContent: 'center', marginBottom: 4 },
  emptyTitle: { color: colors.text, fontSize: 16, fontWeight: '800' },
  emptyText: { color: colors.muted, fontSize: 13, textAlign: 'center' },
});

// apps/client/src/types/calendar.ts
export type CalendarCategory = 'EVENT' | 'LEAD' | 'REMINDER' | 'MEETING' | 'HOLIDAY' | 'SERVICE';
export type CalendarSource = 'CALENDAR_EVENT' | 'LEAD_FOLLOWUP' | 'REMINDER' | 'MEETING';
export type CalendarView = 'month' | 'day' | 'list';

export interface CalendarItem {
  key: string;
  sourceId: string;
  source: CalendarSource;
  category: CalendarCategory;
  title: string;
  description: string | null;
  startAt: string;
  endAt: string | null;
  allDay: boolean;
  leadId: string | null;
  status: string | null;
  version: number | null;
  editable: boolean;
}

export interface CalendarItemsQuery { from: string; to: string; categories: CalendarCategory[] }
export interface CalendarEventInput { title: string; category: 'EVENT' | 'HOLIDAY' | 'SERVICE'; description?: string | null; startAt: string; endAt: string; allDay: boolean; timezone: 'Asia/Kolkata'; requestKey?: string; version?: number }

export const CALENDAR_CATEGORIES: CalendarCategory[] = ['EVENT', 'LEAD', 'REMINDER', 'MEETING', 'HOLIDAY', 'SERVICE'];
export const CALENDAR_CATEGORY_LABELS: Record<CalendarCategory, string> = { EVENT: 'Event', LEAD: 'Lead', REMINDER: 'Reminder', MEETING: 'Meeting', HOLIDAY: 'Holiday', SERVICE: 'Service' };
export const CALENDAR_CATEGORY_COLORS: Record<CalendarCategory, string> = { EVENT: '#F28A24', LEAD: '#1E9B68', REMINDER: '#7C5BC7', MEETING: '#D84B63', HOLIDAY: '#12A8C5', SERVICE: '#778196' };
